INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1273506', 'Battle of Muye', 'The Battle of Muye, Mu, or Muh (c. 1046 BC) was fought between forces of the ancient Chinese Shang dynasty led by Di Xin and the rebel state of Zhou led by King Wu. The Zhou defeated the Shang at Muye and captured the Shang capital Yin, marking the end of the Shang and the establishment of the Zhou dynasty—an event that features prominently in Chinese historiography as an example of the Mandate of Heaven theory that functioned to justify dynastic conquest throughout Chinese history.', -1046, NULL, NULL, NULL, NULL, NULL, 'year', '1046 BCE', 62, 'https://en.wikipedia.org/wiki/Battle_of_Muye'),
  ('Q1349911', 'Rebellion of the Seven States', 'The Rebellion of the Seven States or Revolt of the Seven Kingdoms (simplified Chinese: 七国之乱; traditional Chinese: 七國之亂; pinyin: Qī Guó zhī Luàn) took place in 154 BC against the rule of Emperor Jing of the Western Han dynasty by its regional semi-autonomous kings, to resist the emperor''s attempt to centralize the government further. The rebellion was crushed by the Western Han imperial forces within three months, and the powers of the imperial court grew exponentially afterward.', -154, NULL, NULL, NULL, NULL, NULL, 'year', '154 BCE', 57, 'https://en.wikipedia.org/wiki/Rebellion_of_the_Seven_States'),
  ('Q759985', 'Red Eyebrows', 'The Red Eyebrows (Chinese: 赤眉; pinyin: Chìméi) was one of the two major peasant rebellion movements against Wang Mang''s short-lived Xin dynasty, the other being Lülin. It was so named because the rebels painted their eyebrows red.', 17, NULL, NULL, 27, NULL, NULL, 'year', '17–27', 62, 'https://en.wikipedia.org/wiki/Red_Eyebrows'),
  ('Q1057910', 'Battle of Guandu', 'The Battle of Guandu was fought between the warlords Cao Cao and Yuan Shao in 200 AD in the late Eastern Han dynasty. Cao Cao''s decisive victory against Yuan Shao''s numerically superior forces marked the turning point in their war.', 200, NULL, NULL, NULL, NULL, NULL, 'year', '200', 61, 'https://en.wikipedia.org/wiki/Battle_of_Guandu'),
  ('Q830059', 'Battle of Red Cliffs', 'The Battle of Red Cliffs, also known as the Battle of Chibi, was a decisive naval battle in China that took place during the winter of 208–209 AD. It was fought on the Yangtze River between the forces of warlords controlling different parts of the country during the end of the Han dynasty. The allied forces of Sun Quan, Liu Bei, and Liu Qi based south of the Yangtze defeated the numerically superior forces of the northern warlord Cao Cao.', 208, NULL, NULL, NULL, NULL, NULL, 'year', '208', 69, 'https://en.wikipedia.org/wiki/Battle_of_Red_Cliffs'),
  ('Q1333898', 'Battle of Fei River', 'The Battle of Fei River, also known as the Battle of Feishui (simplified Chinese: 淝水之战; traditional Chinese: 淝水之戰; pinyin: Féishǔi zhī zhàn), took place in the autumn of 383 AD in China, where forces of the Di-led Former Qin dynasty were decisively defeated by the outnumbered army of the Eastern Jin dynasty. The location of the battle, the Fei River, no longer exists but is believed to have flowed through modern Lu''an, Anhui, near the Huai River.', 383, 11, 30, NULL, NULL, NULL, 'day', '30 November 383', 61, 'https://en.wikipedia.org/wiki/Battle_of_Fei_River'),
  ('Q1078359', 'Battle of Yamen', 'The Battle of Yamen (Chinese: 厓門戰役), also known as the Battle of Yashan (Chinese: 厓山海戰), was a naval battle which took place in southern China on 19 March 1279. It is considered to be the last stand of the Song dynasty against the invading forces of the Mongol-led Yuan dynasty.', 1279, 3, 19, NULL, NULL, NULL, 'day', '19 March 1279', 65, 'https://en.wikipedia.org/wiki/Battle_of_Yamen'),
  ('Q112524', 'Red Turban Rebellion', 'The Red Turban Rebellions (Chinese: 紅巾起義; pinyin: Hóngjīn Qǐyì) were uprisings against the Yuan dynasty between 1351 and 1368, eventually leading to its collapse. Remnants of the Yuan imperial court retreated northwards and is thereafter known as the Northern Yuan in historiography.', 1351, NULL, NULL, 1368, NULL, NULL, 'year', '1351–1368', 67, 'https://en.wikipedia.org/wiki/Red_Turban_Rebellions'),
  ('Q112501', 'Revolt of the Three Feudatories', 'The Revolt of the Three Feudatories, (Chinese: 三藩之亂; pinyin: Sānfān zhī luàn) also known as the Rebellion of Wu Sangui, was a rebellion lasting from 1673 to 1681 in the early Qing dynasty of China, during the reign of the Kangxi Emperor (r. 1661–1722).', 1681, 11, NULL, 1681, NULL, NULL, 'month', '1681', 60, 'https://en.wikipedia.org/wiki/Revolt_of_the_Three_Feudatories'),
  ('Q2909446', 'Century of Humiliation', 'The century of humiliation (simplified Chinese: 百年国耻; traditional Chinese: 百年國恥; pinyin: bǎinián guóchǐ) is a Chinese historiographical concept for a period in history beginning with the end of the First Opium War (1839–1842), and terminating with the establishment of the People''s Republic of China in 1949 under the Chinese Communist Party (CCP). The century-long period is typified by the decline, defeat and political fragmentation of the Qing dynasty and the subsequent Republic of China, which led to demoralizing foreign intervention, annexation and subjugation of China by Western powers,…', 1839, NULL, NULL, 1949, NULL, NULL, 'year', '1839–1949', 68, 'https://en.wikipedia.org/wiki/Century_of_humiliation'),
  ('Q192408', 'Taiping Rebellion', 'The Taiping Rebellion (1850–1864) was a civil war in late imperial China fought between the ruling Qing dynasty and the rebelling Taiping Heavenly Kingdom. It was the deadliest civil war in history and the second-deadliest conflict in history overall.', 1850, 12, NULL, 1864, 8, NULL, 'month', 'December 1850 – August 1864', 80, 'https://en.wikipedia.org/wiki/Taiping_Rebellion'),
  ('Q588648', 'Battle of Canton', 'The Battle of Canton (Chinese: 廣州城戰役) was fought by British and French forces against Qing China on 28–31 December 1857 during the Second Opium War. The British High Commissioner, Lord Elgin, was keen to take the city of Canton (Guangzhou) as a demonstration of power and to capture Chinese official Ye Mingchen, who had resisted British attempts to implement the 1842 Treaty of Nanking.', 1857, 12, 28, 1857, 12, 31, 'day', '28 December 1857 – 31 December 1857', 57, 'https://en.wikipedia.org/wiki/Battle_of_Canton_(1857)'),
  ('Q150229', 'Boxer Rebellion', 'The Boxer Rebellion, also known as the Boxer Uprising, Boxer Movement, Yihetuan Movement (traditional Chinese: 義和團運動; simplified Chinese: 义和团运动), or Boxer War, was an uprising in North China between 1899 and 1901, towards the end of the Qing dynasty, by the Society of Righteous and Harmonious Fists. Its members were known as the "Boxers" in English, owing to many of them practicing Chinese martial arts, which at the time were referred to as "Chinese boxing".', 1899, 8, NULL, 1901, 9, NULL, 'month', 'August 1899 – September 1901', 82, 'https://en.wikipedia.org/wiki/Boxer_Rebellion'),
  ('Q592550', 'British expedition to Tibet', 'The British expedition to Tibet, also known as the Younghusband expedition, began in December 1903 and lasted until September 1904. The expedition was effectively a temporary invasion by British Indian Armed Forces under the auspices of the Tibet Frontier Commission, whose purported mission was to establish diplomatic relations and resolve the dispute over the border between Tibet and Sikkim.', 1903, 12, NULL, 1904, 9, NULL, 'month', 'December 1903 – September 1904', 65, 'https://en.wikipedia.org/wiki/British_expedition_to_Tibet'),
  ('Q210800', 'Siege of Port Arthur', 'The siege of Port Arthur (Japanese: 旅順攻囲戦, romanized: Ryojun Kōisen; Russian: Оборона Порт-Артура, romanized: Oborona Port-Artura; August 1, 1904 – January 2, 1905) was the longest and most violent land battle of the Russo-Japanese War. Port Arthur, the deep-water port and Russian naval base at the tip of the Liaodong Peninsula in Manchuria, had been widely regarded as one of the most strongly fortified positions in the world.', 1904, 8, 1, 1905, 1, 2, 'day', '1 August 1904 – 2 January 1905', 63, 'https://en.wikipedia.org/wiki/Siege_of_Port_Arthur'),
  ('Q2440191', 'Battle of Liaoyang', 'The Battle of Liaoyang (遼陽会戦, Ryōyō-kaisen; 25 August – 3 September 1904) (Russian: Сражение при Ляояне) was a major land battle of the Russo-Japanese War, on the outskirts of the city of Liaoyang in present-day Liaoning Province, China. The city was of great strategic importance as the major Russian military center for southern Manchuria, and a major population center on the main line on the Russian South Manchurian Railway connecting Port Arthur with Mukden.', 1904, 8, 25, 1904, 9, 5, 'day', '25 August 1904 – 5 September 1904', 59, 'https://en.wikipedia.org/wiki/Battle_of_Liaoyang'),
  ('Q384091', 'Battle of Mukden', 'The Battle of Mukden (19 February – 10 March 1905) was fought in the Russo-Japanese War between the Russian Empire and the Empire of Japan near the town of Mukden (now Shenyang, China). Involving close to 550,000 troops and resulting in over 150,000 casualties, it was the largest battle of the war, as well as the last major engagement on land.', 1905, 2, 6, 1905, 2, 25, 'day', '6 February 1905 – 25 February 1905', 64, 'https://en.wikipedia.org/wiki/Battle_of_Mukden'),
  ('Q339291', 'Wuchang Uprising', 'The Wuchang Uprising was an armed rebellion against the ruling Qing dynasty that took place in Wuchang (now Wuchang District of Wuhan) in the Chinese province of Hubei on 10 October 1911, beginning the 1911 Revolution that successfully overthrew China''s last imperial dynasty, the Qing dynasty. It was led by elements of the New Army, influenced by revolutionary ideas from Tongmenghui.', 1911, 10, 10, 1911, 12, 1, 'day', '10 October 1911 – 1 December 1911', 67, 'https://en.wikipedia.org/wiki/Wuchang_Uprising'),
  ('Q706563', 'Siege of Tsingtao', 'The Siege of Tsingtao (German: Belagerung von Tsingtau; Japanese: 青島の戦い; simplified Chinese: 青岛战役; traditional Chinese: 青島戰役) was the attack on the German port of Qingdao (Tsingtao) from Jiaozhou Bay during World War I by Japan and the United Kingdom. The siege was waged against Imperial Germany between 27 August and 7 November 1914.', 1914, 8, 27, 1914, 11, 7, 'day', '27 August 1914 – 7 November 1914', 65, 'https://en.wikipedia.org/wiki/Siege_of_Tsingtao'),
  ('Q361', 'World War I', 'World War I, or the First World War (28 July 1914 – 11 November 1918), also known as the Great War, was a global conflict between two coalitions: the Allies (or Entente) and the Central Powers. One of the deadliest conflicts in history, World War I caused 15 to 22 million deaths, including those resulting from war crimes and genocides.', 1918, 11, 11, 1918, 11, 11, 'day', '11 November 1918', 100, 'https://en.wikipedia.org/wiki/World_War_I'),
  ('Q476634', 'Nanchang Uprising', 'The Nanchang Uprising of August 1927 was the point at which conflict between the Chinese Communist Party and the Nationalist Party of China (Kuomintang) became an outright rebellion. This began the Chinese Civil War.', 1927, 8, 1, NULL, NULL, NULL, 'day', '1 August 1927', 66, 'https://en.wikipedia.org/wiki/Nanchang_Uprising'),
  ('Q992318', 'Autumn Harvest Uprising', 'The Autumn Harvest Uprising was an insurrection that took place in Hunan and Jiangxi provinces of China, on September 7, 1927, led by Mao Zedong, who established a short-lived Hunan Soviet. After initial success, the uprising was brutally put down by Kuomintang forces.', 1927, 9, 7, NULL, NULL, NULL, 'day', '7 September 1927', 58, 'https://en.wikipedia.org/wiki/Autumn_Harvest_Uprising'),
  ('Q1073476', 'Northern Expedition', 'The Northern Expedition was a military campaign launched by the National Revolutionary Army (NRA) of the Kuomintang (KMT) against the Beiyang government and other regional warlords in 1926. The purpose of the campaign was to reunify China, which had become fragmented in the aftermath of the 1911 Revolution.', 1928, 12, 29, 1928, NULL, NULL, 'day', '1928', 69, 'https://en.wikipedia.org/wiki/Northern_Expedition'),
  ('Q708451', 'defense of the Great Wall', 'The defense of the Great Wall (traditional Chinese: 長城抗戰; simplified Chinese: 长城抗战; pinyin: Chángchéng Kàngzhàn) (January 1 – May 31, 1933) was a campaign between the armies of the Republic of China and the Empire of Japan, which took place before the Second Sino-Japanese War officially commenced in 1937 and after the Japanese invasion of Manchuria in 1931. It is known in Japanese as Operation Nekka (熱河作戰, Nekka Sakusen) and in many English sources as the First Battle of Hopei.', 1933, 5, 31, 1933, 5, 21, 'day', '31 May 1933 – 21 May 1933', 56, 'https://en.wikipedia.org/wiki/Defense_of_the_Great_Wall'),
  ('Q219230', 'Marco Polo Bridge incident', 'The Marco Polo Bridge incident, also known as the Lugou Bridge incident or the July 7 incident, was a three-day battle that began on 7 July 1937 in the district of Beijing between the 29th Army of the National Revolutionary Army of the Republic of China and the Imperial Japanese Army. Since the Japanese invasion of Manchuria in 1931, there had been many small incidents along the rail line connecting Beijing with the port of Tianjin, but all had subsided.', 1937, 7, 7, 1937, 7, 9, 'day', '7 July 1937 – 9 July 1937', 74, 'https://en.wikipedia.org/wiki/Marco_Polo_Bridge_incident'),
  ('Q709421', 'Battle of Xuzhou', 'The Battle of Xuzhou was a military campaign between the Empire of Japan and the Republic of China forces in early 1938 during the Second Sino-Japanese War. It lasted for more than three months, with both sides taking heavy casualties and claiming victories.', 1938, 3, 24, 1938, 5, 1, 'day', '24 March 1938 – 1 May 1938', 57, 'https://en.wikipedia.org/wiki/Battle_of_Xuzhou'),
  ('Q2038907', 'Battle of Wuhan', 'The Battle of Wuhan (traditional Chinese: 武漢會戰; simplified Chinese: 武汉会战; Japanese: 武漢作戦 (ぶかんさくせん)), popularly known to the Chinese as the Defense of Wuhan (traditional Chinese: 武漢保衛戰; simplified Chinese: 武汉保卫战), and to the Japanese as the Capture of Wuhan, was the largest, longest, and bloodiest battle of the Second Sino-Japanese War. Engagements took place across vast areas of Anhui, Henan, Jiangxi, Zhejiang, and Hubei provinces over four and a half months.', 1938, 10, 27, NULL, NULL, NULL, 'day', '27 October 1938', 61, 'https://en.wikipedia.org/wiki/Battle_of_Wuhan'),
  ('Q709333', 'Battle of Changsha', 'The First Battle of Changsha (17 September 1939 – 6 October 1939; Chinese: 第一次長沙會戰) was the first of four attempts by Japan to take the city of Changsha, Hunan, during the second Sino-Japanese War.', 1939, NULL, NULL, 1939, 10, 6, 'year', '1939', 61, 'https://en.wikipedia.org/wiki/Battle_of_Changsha_(1939)'),
  ('Q697059', 'Battle of Hong Kong', 'The Battle of Hong Kong (8–25 December 1941), also known as the Defence of Hong Kong and the Fall of Hong Kong, was one of the first battles of the Pacific War in World War II. On the same morning as the attack on Pearl Harbor, forces of the Empire of Japan attacked the British Crown colony of Hong Kong around the same time that Japan declared war on Britain. The Hong Kong garrison consisted of British, Indian and Canadian units, the Auxiliary Defence Units, and the Hong Kong Volunteer Defence Corps (HKVDC).', 1941, 12, 8, 1941, 12, 25, 'day', '8 December 1941 – 25 December 1941', 65, 'https://en.wikipedia.org/wiki/Battle_of_Hong_Kong'),
  ('Q1759660', 'Battle of Changsha', 'The (Second) Battle of Changsha (6 September – 8 October 1941; Chinese: 第二次長沙會戰) was Japan''s second attempt at taking the city of Changsha, China, the capital of Hunan Province, as part of the Second Sino-Japanese War.', 1941, 9, 6, 1941, 10, 8, 'day', '6 September 1941 – 8 October 1941', 57, 'https://en.wikipedia.org/wiki/Battle_of_Changsha_(1941)'),
  ('Q712505', 'Battle of Changde', 'The Battle of Changde (Battle of Changteh; traditional Chinese: 常德會戰; simplified Chinese: 常德会战; pinyin: Chángdé Huìzhàn) was a major engagement in the Second Sino-Japanese War in and around the Chinese city of Changde (Changteh) in the province of Hunan. The purpose of the Japanese offensive was to maintain pressure on the Chinese National Revolutionary Army to reduce its combat ability in the region and its ability to reinforce the Burma Campaign.', 1943, 11, 2, 1943, 12, 20, 'day', '2 November 1943 – 20 December 1943', 56, 'https://en.wikipedia.org/wiki/Battle_of_Changde'),
  ('Q738854', '1950 Assam–Tibet earthquake', 'The 1950 Assam–Tibet earthquake, also known as the Assam earthquake, occurred on 15 August and had a moment magnitude of 8.7. The epicentre was located in the Mishmi Hills.', 1950, 8, 15, NULL, NULL, NULL, 'day', '15 August 1950', 57, 'https://en.wikipedia.org/wiki/1950_Assam%E2%80%93Tibet_earthquake'),
  ('Q1773984', 'Battle of Chamdo', 'The Battle of Chamdo (or Qamdo; Chinese: 昌都战役) occurred from 6 to 24 October 1950. It was a military campaign by the People''s Republic of China (PRC) to capture the Chamdo region from a de facto independent Tibetan state.', 1950, 10, 24, 1951, 5, NULL, 'day', '24 October 1950 – May 1951', 62, 'https://en.wikipedia.org/wiki/Battle_of_Chamdo'),
  ('Q2862267', 'Korean Armistice Agreement', 'The Korean Armistice Agreement (Korean: 한국정전협정; Hanja: 韓國停戰協定) is an armistice that brought about a cessation of hostilities of the Korean War. It was signed by United States Army Lieutenant General William Harrison Jr.', 1953, 7, 27, NULL, NULL, NULL, 'day', '27 July 1953', 65, 'https://en.wikipedia.org/wiki/Korean_Armistice_Agreement'),
  ('Q2454958', 'Great Chinese Famine', 'The Great Chinese Famine (Chinese: 三年大饥荒; lit. ''three years of great famine'') was a famine that occurred between 1959 and 1961 in the People''s Republic of China (PRC).', 1959, NULL, NULL, 1961, NULL, NULL, 'year', '1959–1961', 75, 'https://en.wikipedia.org/wiki/Great_Chinese_Famine'),
  ('Q208694', 'Sino-Indian War', 'The Sino-Indian War, also known as the China–India War or the Indo-China War, was an armed conflict between China and India that took place from October to November 1962. It was a military escalation of the Sino-Indian border dispute.', 1962, 10, 20, 1962, 11, 21, 'day', '20 October 1962 – 21 November 1962', 76, 'https://en.wikipedia.org/wiki/Sino-Indian_War'),
  ('Q8690', 'Cultural Revolution', 'The Cultural Revolution, formally known as the Great Proletarian Cultural Revolution, was a sociopolitical movement in the People''s Republic of China (PRC). It was launched by Mao Zedong, chairman of the Chinese Communist Party, in 1966 and lasted until his death in 1976.', 1966, 5, 16, 1976, 10, 6, 'day', '16 May 1966 – 6 October 1976', 91, 'https://en.wikipedia.org/wiki/Cultural_Revolution'),
  ('Q462195', '1976 Tangshan earthquake', 'The 1976 Tangshan earthquake (Chinese: 唐山大地震; pinyin: Tángshān dà dìzhèn; lit. ''Great Tangshan earthquake'') occurred at 19:42:55 UTC on 27 July (03:42:55, 28 July local time).', 1976, 7, 28, NULL, NULL, NULL, 'day', '28 July 1976', 75, 'https://en.wikipedia.org/wiki/1976_Tangshan_earthquake'),
  ('Q1191151', 'Tiananmen incident', 'The 1976 Tiananmen incident or the April 5 Tiananmen incident (Chinese: 四五天安门事件) was a mass gathering and protest that took place on 4–5 April 1976, at Tiananmen Square in Beijing, China. The incident occurred on the traditional day of mourning, the Qingming Festival, after the Nanjing incident, and was triggered by the death of Premier Zhou Enlai earlier that year.', 1976, 4, 5, NULL, NULL, NULL, 'day', '5 April 1976', 58, 'https://en.wikipedia.org/wiki/1976_Tiananmen_incident'),
  ('Q99717', '1989 Tiananmen Square protests and massacre', 'Protests led by students and workers, known in China as the June Fourth Incident, were held in Tiananmen Square in Beijing, China, from 15 April to 4 June 1989. After weeks of unsuccessful attempts between the demonstrators and the Chinese government to find a peaceful resolution, the Chinese government initiated martial law in late May and deployed troops to occupy the square on the night of 3 June in what is referred to as the Tiananmen Square massacre.', 1989, NULL, NULL, 1989, 6, 4, 'year', '1989', 85, 'https://en.wikipedia.org/wiki/1989_Tiananmen_Square_protests_and_massacre'),
  ('Q705373', 'Third Taiwan Strait Crisis', 'The Third Taiwan Strait Crisis, also called the 1995–1996 Taiwan Strait Crisis, or the 1996 Taiwan Strait Crisis, was the effect of a series of missile tests conducted by the People''s Republic of China (PRC) in the waters surrounding Taiwan, including the Taiwan Strait, from 21 July 1995 to 23 March 1996. The first set of missiles fired in mid-to-late 1995 was allegedly intended to send a strong signal to the Republic of China government (ROC) under President Lee Teng-hui, who had been seen as "moving its foreign policy away from the One-China policy", as claimed by the PRC. The second set…', 1995, 7, 21, 1996, 3, 23, 'day', '21 July 1995 – 23 March 1996', 61, 'https://en.wikipedia.org/wiki/Third_Taiwan_Strait_Crisis'),
  ('Q152033', '2008 Sichuan earthquake', 'An earthquake occurred in the province of Sichuan, China at 14:28:01 China Standard Time on May 12, 2008. Measuring at 8.0 Ms (7.9–8.3 Mw), the earthquake''s epicenter was located 80 kilometres (50 mi) west-northwest of Chengdu, the provincial capital, with a focal depth of 19 km (12 mi).', 2008, 5, 12, NULL, NULL, NULL, 'day', '12 May 2008', 76, 'https://en.wikipedia.org/wiki/2008_Sichuan_earthquake'),
  ('Q844505', 'July 2009 Ürümqi riots', 'A series of violent riots over several days broke out on 5 July 2009 in Ürümqi, the capital city of the Xinjiang Uyghur Autonomous Region, in northwestern China. The first day''s rioting, which involved at least 1,000 Uyghurs, began as a protest, but escalated into violent attacks that mainly targeted Han people.', 2009, 7, 5, NULL, NULL, NULL, 'day', '5 July 2009', 64, 'https://en.wikipedia.org/wiki/July_2009_%C3%9Cr%C3%BCmqi_riots'),
  ('Q381766', '2010 Yushu earthquake', 'The 2010 Yushu earthquake struck on April 14 and registered a magnitude of 6.9 Mw (USGS, EMSC) or 7.1 Ms (CEA, CENC). It originated in Yushu, Qinghai, China, at 7:49 am local time (23:49 April 13 UTC).', 2010, 4, 13, NULL, NULL, NULL, 'day', '13 April 2010', 65, 'https://en.wikipedia.org/wiki/2010_Yushu_earthquake'),
  ('Q150495', '2011 Tarlay earthquake', 'The 2011 Shan earthquake occurred on 24 March in Shan State, Myanmar. The earthquake measured Mw 6.8 and had an epicenter northwest of the border between Myanmar, Thailand and Laos.', 2011, 3, 24, NULL, NULL, NULL, 'day', '24 March 2011', 61, 'https://en.wikipedia.org/wiki/2011_Shan_earthquake'),
  ('Q1155993', '2011 Chinese pro-democracy protests', 'The 2011 Chinese pro-democracy protests, also known as the Greater Chinese Democratic Jasmine Revolution (Chinese: 中国茉莉花活动), refer to public assemblies in over a dozen cities in the People''s Republic of China starting on 20 February 2011, inspired by and named after the Jasmine Revolution in Tunisia; the actions that took place at protest sites, and the response by the Chinese government to the calls and action. Initially, organizers suggested shouting slogans on 20 February.', 2011, NULL, NULL, NULL, NULL, NULL, 'year', '2011', 60, 'https://en.wikipedia.org/wiki/2011_Chinese_pro-democracy_protests'),
  ('Q11547847', '2013 Lushan earthquake', 'The Lushan earthquake or Ya''an earthquake (Standard Tibetan: གཡག་རྔ་ཡི་ས་ཡོམ་, Yak-ngai Sayom) occurred at 08:02 Beijing Time (00:02 UTC) on April 20, 2013. The epicenter was located in Lushan County, Ya''an, Sichuan, about 116 km (72 mi) from Chengdu along the Longmenshan Fault in the same province heavily impacted by the 2008 Sichuan earthquake.', 2013, 4, 20, NULL, NULL, NULL, 'day', '20 April 2013', 60, 'https://en.wikipedia.org/wiki/2013_Lushan_earthquake'),
  ('Q15856657', '2014 Kunming attack', 'On 1 March 2014, a group of five knife-wielding terrorists attacked passengers in the Kunming Railway Station in Kunming, Yunnan, China, killing 31 people, and wounding 143 others. The attackers pulled out long-bladed knives and stabbed and slashed passengers at random.', 2014, 3, 1, NULL, NULL, NULL, 'day', '1 March 2014', 57, 'https://en.wikipedia.org/wiki/2014_Kunming_attack'),
  ('Q17483279', '2014 Ludian earthquake', 'The 2014 Ludian earthquake struck Ludian County, Yunnan, China, with a moment magnitude of 6.2 on 3 August. The earthquake killed at least 615 people, injuring at least 2,400 others.', 2014, 8, 3, NULL, NULL, NULL, 'day', '3 August 2014', 59, 'https://en.wikipedia.org/wiki/2014_Ludian_earthquake'),
  ('Q18145420', '2014 Hong Kong protests', 'A series of sit-in street protests, often called the Umbrella Revolution and sometimes used interchangeably with Umbrella Movement, or Occupy Movement, occurred in Hong Kong from 26 September to 15 December 2014. The protests began after the Standing Committee of the National People''s Congress (NPCSC) issued a decision regarding proposed reforms to the Hong Kong electoral system.', 2014, NULL, NULL, 2014, 12, 15, 'year', '2014', 70, 'https://en.wikipedia.org/wiki/2014_Hong_Kong_protests'),
  ('Q35519507', '2017 Jiuzhaigou earthquake', 'The 2017 Jiuzhaigou earthquake occurred on 8 August 2017, in Zhangzha Town, Jiuzhaigou County, Ngawa Prefecture, Sichuan Province, China. The earthquake was registered at Ms 7.0 and killed 29 people in the mountainous region of northern Sichuan.', 2017, 8, 8, NULL, NULL, NULL, 'day', '8 August 2017', 57, 'https://en.wikipedia.org/wiki/2017_Jiuzhaigou_earthquake'),
  ('Q64509602', '2019–2020 Hong Kong protests', 'discuss on talk page and gain consensus for change From 2019 until 2020, protests were held in Hong Kong in response to the Hong Kong government''s introduction of a bill to amend the Fugitive Offenders Ordinance in regard to extradition. It was the largest series of demonstrations in the history of Hong Kong.', 2019, 3, 15, NULL, NULL, NULL, 'day', '15 March 2019', 79, 'https://en.wikipedia.org/wiki/2019%E2%80%932020_Hong_Kong_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q107596384', '2021 Henan floods', 'The 2021 Henan floods were floods in China, specifically the province of Henan, which experienced flooding between 17 and 31 July 2021 as a result of heavy rainfall. On July 20, Zhengzhou, the provincial capital, recorded 201.9 millimetres (7.95 in) of rainfall within an hour, the highest ever figure recorded since measurements began in 1951.', 2021, NULL, NULL, NULL, NULL, NULL, 'year', '2021', 57, 'https://en.wikipedia.org/wiki/2021_Henan_floods'),
  ('Q111313251', 'China Eastern Airlines Flight 5735', 'China Eastern Airlines Flight 5735 (MU5735) was a domestic passenger flight from Kunming Changshui International Airport to Guangzhou Baiyun International Airport in China. At 14:23 China Standard Time (06:23 UTC) on 21 March 2022, the Boeing 737-800 aircraft descended steeply mid-flight and struck the ground at high speed in Teng County, Wuzhou, Guangxi, killing all 132 passengers and crew on board.', 2022, 3, 21, NULL, NULL, NULL, 'day', '21 March 2022', 69, 'https://en.wikipedia.org/wiki/China_Eastern_Airlines_Flight_5735'),
  ('Q113717492', '2022 Luding earthquake', 'A Mw 6.7 (Ms 6.8) earthquake struck Luding County in Sichuan province, China on 5 September 2022 at 12:52:19 local time. The epicenter was located 226 km (140 mi) from Chengdu, or 43 km (27 mi) southeast of Kangding.', 2022, 9, 5, NULL, NULL, NULL, 'day', '5 September 2022', 57, 'https://en.wikipedia.org/wiki/2022_Luding_earthquake'),
  ('Q115468992', '2022 COVID-19 protests in China', 'A series of protests against COVID-19 lockdowns began in mainland China in November 2022. Colloquially referred to as the White Paper Protests (Chinese: 白纸抗议; pinyin: Bái zhǐ kàngyì) or the A4 Revolution (Chinese: 白纸革命; pinyin: Bái zhǐ gémìng), the demonstrations started in response to measures taken by the Chinese government to prevent the spread of COVID-19 in the country, including implementing a zero-COVID policy.', 2022, 11, 27, 2023, 1, 8, 'day', '27 November 2022 – 8 January 2023', 70, 'https://en.wikipedia.org/wiki/2022_COVID-19_protests_in_China'),
  ('Q123913022', '2023 Jishishan earthquake', 'On 18 December 2023 at around 23:59:30 CST, an earthquake with a magnitude of 5.9–6.2 struck Jishishan County, in Gansu Province, China. The shallow thrust faulting earthquake struck a densely populated area on the border between the provinces of Gansu and Qinghai.', 2023, 12, 18, NULL, NULL, NULL, 'day', '18 December 2023', 60, 'https://en.wikipedia.org/wiki/2023_Jishishan_earthquake'),
  ('Q131692964', '2025 Tibet earthquake', 'On 7 January 2025 at 09:05 CST (UTC+8), an earthquake measuring Mw 7.1 struck Tingri County, located in the Shigatse prefecture-level city of the Tibet Autonomous Region of Southwestern China. Between 126 and 400 people were killed and 338 were injured in the region.', 2025, 1, 7, NULL, NULL, NULL, 'day', '7 January 2025', 71, 'https://en.wikipedia.org/wiki/2025_Tibet_earthquake'),
  ('Q141182413', '2026 Nepal–Tibet floods', 'On the morning of 26 August 2026, a series of flash floods and debris flows destroyed the Gyirong Port on the China–Nepal border and struck dozens of settlements along a 72 km (45 mi) stretch of the Trishuli River in Nepal. These events are also known as the 2026 Nepal-China floods, Bhotekoshi flood, or Rasuwa flood.', 2026, 8, 26, NULL, NULL, NULL, 'day', '26 August 2026', 77, 'https://en.wikipedia.org/wiki/2026_Nepal%E2%80%93Tibet_floods');
